<?php
namespace App\Policies;
use App\Models\{ProjectConstruction,User}; use App\Policies\Concerns\CompanyOwnedPolicy; use Illuminate\Auth\Access\HandlesAuthorization;
class ProjectConstructionPolicy { use HandlesAuthorization, CompanyOwnedPolicy; public function viewAny(User $u):bool{return $u->can('view_any_project::construction');} public function view(User $u,ProjectConstruction $r):bool{return $this->canForRecord($u,'view_project::construction',$r);} public function create(User $u):bool{return $u->can('create_project::construction');} public function update(User $u,ProjectConstruction $r):bool{return in_array($r->status,['planned','in_progress'],true)&&$this->canForRecord($u,'update_project::construction',$r);} public function delete(User $u,ProjectConstruction $r):bool{return $r->status==='planned'&&!$r->workPackages()->exists()&&$this->canForRecord($u,'delete_project::construction',$r);} public function deleteAny(User $u):bool{return false;} public function forceDelete(User $u,ProjectConstruction $r):bool{return false;} public function forceDeleteAny(User $u):bool{return false;} public function restore(User $u,ProjectConstruction $r):bool{return false;} public function restoreAny(User $u):bool{return false;} public function replicate(User $u,ProjectConstruction $r):bool{return false;} public function reorder(User $u):bool{return false;} public function start(User $u,ProjectConstruction $r):bool{return $this->canForRecord($u,'start_project_construction',$r);} public function complete(User $u,ProjectConstruction $r):bool{return $this->canForRecord($u,'complete_project_construction',$r);} public function cancel(User $u,ProjectConstruction $r):bool{return $this->canForRecord($u,'cancel_project_construction',$r);} }
